// CSD_RATIONALE_BEGIN
// Root-cause analysis of current 6.1% vs 40.8% best:
// Attempt 64's two-token minimum and "SHORTEST expression" guidance forced the model
// into very short (avg 2.26-token) spans. Attempt 63's immediate CloseSpanIfComplete
// produced single-variable spans. The best attempt (40.8%) used next=="<<" (fragile)
// and simple per-token AdaptiveConstrainedStep, giving avg 3.26-token valid spans.
//
// The remaining 59.7pp gap to goal is explained by the model splitting one expression
// across multiple spans: "<<n * frac_1>> * <<frac_2>>" instead of "<<n * frac_1 * frac_2>>".
// The answer extractor takes the LAST span, so fragmented expressions always yield wrong answers.
//
// Two targeted improvements over the best attempt:
//
// 1. Replace per-token AdaptiveConstrainedStep inside spans with ConstrainedSymbolInGenerated
//    (budget=20): this helper generates up to 20 tokens then returns the LONGEST complete-prefix
//    subsequence, naturally producing longer, more complete arithmetic expressions. When the
//    model would naturally emit ">>" to close, ConstrainedSymbol trims at that point and returns
//    the full preceding arithmetic expression — avoiding premature single-token closure.
//
// 2. Fix delimiter detection: RenderedEndsWith(generated, "<<") instead of next == "<<".
//    This correctly handles tokenizer-split delimiters.
//
// 3. Guidance updated to explicitly prohibit splitting one expression across spans.
//
// Structure preserved from best attempt: free unconstrained outside spans, EnterObservedConstrainedSpan
// on "<<" detection, CloseConstrainedSpan on IsCompletePrefix, CloseSpanWithinBudget at budget
// pressure, force-open final span near exhaustion.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span / UnconstrainedStep branch: insideConstrainedOut is false, implication vacuous.
//   When RenderedEndsWith fires, EnterObservedConstrainedSpan sets currentConstrainedOut := [];
//   parser.IsValidPrefix([]) holds by method precondition.
//
//   OpenConstrainedSpan branch (force-open): sets currentConstrainedOut := []; same argument.
//
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making implication vacuously
//   true regardless of currentConstrainedOut (which is also cleared to []).
//
//   CloseSpanWithinBudget branch: postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
//   ConstrainedSymbolInGenerated branch: postcondition guarantees parser.IsValidPrefix(cout);
//   we assign currentConstrainedOut := cout. insideConstrainedOut remains true (set on span entry,
//   cleared only in close branches). If hitEos we break; invariant holds on exit since
//   insideConstrainedOut may be true but the method postcondition only requires the implication.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Initialization: equality holds (generated == generatedPrefix, steps == 0). ✓
//
//   UnconstrainedStep: steps += 1; generated grows by at most 1 token (EOS breaks without
//   appending). EnterObservedConstrainedSpan leaves generated unchanged. ✓
//
//   OpenConstrainedSpan: appends "<<" (one token), steps += 1. ✓
//
//   CloseConstrainedSpan: appends ">>" (one token), steps += 1. ✓
//
//   CloseSpanWithinBudget with closeBudget = maxSteps - steps: postcondition gives
//   |generated_new| <= |generated_old| + closeBudget = |generated_old| + (maxSteps - steps_old).
//   After steps := maxSteps: |generated_new| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   ConstrainedSymbolInGenerated with symbolBudget: postcondition gives |gout| <= |generated| + stepsUsed
//   (visible growth <= token budget consumed). After steps += stepsUsed:
//   |gout| <= |generatedPrefix| + steps_before + stepsUsed = |generatedPrefix| + steps_after.
//   And steps_after = steps_before + stepsUsed <= steps_before + symbolBudget
//   <= steps_before + (maxSteps - steps_before - 3) = maxSteps - 3 < maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap each arithmetic expression inside << >>.\n" +
  "CRITICAL: Write ONE complete expression per span — never split across spans.\n" +
  "Good: <<n * frac_1 * frac_2>>. Bad: <<n * frac_1>> * <<frac_2>>.\n" +
  "Good: <<n * price - discount>>. Bad: <<n * price>> - <<discount>>.\n" +
  "Use // for integer division. The LAST << >> span must be the single complete final answer expression.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force open one final constrained span for the answer.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // RenderedEndsWith handles tokenizer-split "<<" correctly.
        if RenderedEndsWith(generated, "<<") {
          var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := og;
          insideConstrainedOut := oi;
          currentConstrainedOut := oc;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Expression is complete — close the span.
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget: use CloseSpanWithinBudget to reach a completable state and close.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Use ConstrainedSymbolInGenerated with a multi-token budget to produce longer,
      // more complete arithmetic expressions instead of single tokens.
      // symbolBudget <= maxSteps - steps - 3, ensuring steps never exceeds maxSteps - 3.
      var symbolBudget: nat := if maxSteps - steps > 23 then 20 else maxSteps - steps - 3;
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var gout, cout, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := gout;
      currentConstrainedOut := cout;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

